 "content": "from collections import Counter, deque


def transform(grid):
    """Recolor the largest foreground component touching the grid border to 5."""
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    height, width = len(grid), len(grid[0])
    background = Counter(value for row in grid for value in row).most_common(1)[0][0]
    visited = [[False] * width for _ in range(height)]
    candidates = []

    for r in range(height):
        for c in range(width):
            color = grid[r][c]
            if visited[r][c] or color == background:
                continue
            component = []
            touches_border = False
            queue = deque([(r, c)])
            visited[r][c] = True
            while queue:
                cr, cc = queue.popleft()
                component.append((cr, cc))
                if cr == 0 or cc == 0 or cr == height - 1 or cc == width - 1:
                    touches_border = True
                for nr, nc in ((cr - 1, cc), (cr + 1, cc), (cr, cc - 1), (cr, cc + 1)):
                    if (0 <= nr < height and 0 <= nc < width
                            and not visited[nr][nc] and grid[nr][nc] == color):
                        visited[nr][nc] = True
                        queue.append((nr, nc))
            if touches_border:
                candidates.append(component)

    if candidates:
        target = max(candidates, key=len)
        for r, c in target:
            out[r][c] = 5
    return out
